files.scripts/check_bundle.py:
#!/usr/bin/env python3
"""Verify the local skill bundle without network or third-party packages."""
from __future__ import annotations

import ast
import hashlib
import json
from pathlib import Path
import re
import sys


def check(root):
    root = Path(root).resolve()
    issues = []
    manifest_path = root / 'bundle-manifest.json'
    try:
        manifest = json.loads(manifest_path.read_text(encoding='utf-8'))
    except (OSError, ValueError) as exc:
        return [f'cannot read bundle-manifest.json: {exc}']
    records = manifest.get('files') if isinstance(manifest, dict) else None
    if not isinstance(records, list) or not records:
        return ['bundle manifest requires nonempty files array']
    seen = set()
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('path'), str):
            issues.append('invalid file record')
            continue
        name = record['path']
        p = (root / name).resolve()
        if Path(name).is_absolute() or re.match(r'^[A-Za-z]:',name) or '\\' in name or not p.is_relative_to(root):
            issues.append(f'path escapes or is not portable: {name}')
            continue
        if name in seen:
            issues.append(f'duplicate file record: {name}')
        seen.add(name)
        try:
            raw = p.read_bytes()
            if len(raw) != record.get('bytes') or hashlib.sha256(raw).hexdigest() != record.get('sha256'):
                issues.append(f'file changed: {name}')
            if p.suffix == '.md':
                for link in re.findall(r'\]\(([^)]+)\)',raw.decode('utf-8-sig')):
                    if '://' in link or link.startswith('#'):
                        continue
                    dest = (p.parent / link.split('#',1)[0]).resolve()
                    if not dest.is_relative_to(root) or not dest.is_file():
                        issues.append(f'local reference missing or external: {name} -> {link}')
            if p.suffix == '.py':
                ast.parse(raw.decode('utf-8-sig'))
        except (OSError, ValueError, SyntaxError) as exc:
            issues.append(f'cannot verify {name}: {exc}')
    required = {'SKILL.md','agents/openai.yaml','references/requirements.md','references/portability.md',
                'references/user-standard.txt',
                'scripts/validate_delivery.py','scripts/selftest.py','scripts/check_bundle.py',
                'assets/example-project/delivery.json','使用说明.md','验证报告.md'}
    for name in sorted(required - seen):
        issues.append(f'required bundled resource not inventoried: {name}')
    return issues


def main():
    root = Path(sys.argv[1]) if len(sys.argv)>1 else Path(__file__).resolve().parents[1]
    issues = check(root)
    print(json.dumps({'ok':not issues,'issues':issues,'network_required':False},ensure_ascii=False,indent=2))
    return 1 if issues else 0


if __name__ == '__main__':
    sys.exit(main())

