#!/usr/bin/env python3
"""对白保真辅助比对：定位原文引语在剧本中的落点，报告缺失与疑似改写。

只做定位与候选提示，不做质量判定。是否属于"暂缓未用/用户批准改动"以
对白台账和人工回读原文为准。仅用 Python 标准库，不联网、不改文件。

用法：
  python check_dialogue.py --source 输入/原著.txt --script 剧本.md --ledger 对白台账.md
  python check_dialogue.py --source 输入 --script 剧集/ --json out.json
"""
from __future__ import annotations

import argparse
import difflib
import json
import re
import sys
import unicodedata
from pathlib import Path

QUOTE_RES = [
    re.compile(r'“([^”\n]{1,300})”'),
    re.compile(r'「([^」\n]{1,300})」'),
    re.compile(r'『([^』\n]{1,300})』'),
    re.compile(r'"([^"\n]{1,300})"'),
]
TEXT_SUFFIXES = {'.txt', '.md', '.markdown'}


def read_text(path: Path) -> str:
    raw = path.read_bytes()
    for enc in ('utf-8-sig', 'utf-8', 'gb18030'):
        try:
            return raw.decode(enc)
        except UnicodeDecodeError:
            continue
    return raw.decode('utf-8', 'replace')


def norm(text: str) -> str:
    """去空白与标点，保留汉字、字母、数字，用于子串比对。"""
    out = []
    for ch in text:
        if ch.isspace():
            continue
        cat = unicodedata.category(ch)
        if cat.startswith('P') or cat in ('Sm', 'Sk'):
            continue
        out.append(ch.lower())
    return ''.join(out)


TONE_MAP = {'?': '？', '!': '！', '~': '～'}
TONE_CHARS = set('…—？！?～~')


def tone_profile(text: str):
    """统计承载语气的标点（省略号、破折号、问号、感叹号、波浪号），全角半角归一。"""
    prof = {}
    for ch in text:
        ch = TONE_MAP.get(ch, ch)
        if ch in TONE_CHARS:
            prof[ch] = prof.get(ch, 0) + 1
    return prof


def inner_quotes(line: str):
    out = []
    for pattern in QUOTE_RES:
        out.extend(m.group(1) for m in pattern.finditer(line))
    return out


def lost_tone(quote: str, line: str):
    """找出剧本里被抹掉的语气标点；完全不同的句子不在此处判定。"""
    nq = norm(quote)
    target = line
    for cand in inner_quotes(line):
        if nq in norm(cand):
            target = cand
            break
    src = tone_profile(quote)
    dst = tone_profile(target)
    return [{'mark': ch, 'source': cnt, 'script': dst.get(ch, 0)}
            for ch, cnt in src.items() if dst.get(ch, 0) < cnt]


def iter_files(paths):
    for p in paths:
        path = Path(p)
        if path.is_dir():
            for f in sorted(path.rglob('*')):
                if f.is_file() and f.suffix.lower() in TEXT_SUFFIXES:
                    yield f
        elif path.is_file():
            yield path
        else:
            raise FileNotFoundError(str(path))


def load_lines(paths):
    """返回 [(file, line_no, text, norm_text)]，并给一份全文拼接串。"""
    rows = []
    for f in iter_files(paths):
        for i, line in enumerate(read_text(f).splitlines(), 1):
            rows.append((str(f), i, line, norm(line)))
    whole = ''.join(row[3] for row in rows)
    return rows, whole


def extract_quotes(paths, min_len):
    quotes = []
    for f in iter_files(paths):
        for i, line in enumerate(read_text(f).splitlines(), 1):
            seen_in_line = set()
            for pattern in QUOTE_RES:
                for m in pattern.finditer(line):
                    q = m.group(1).strip()
                    nq = norm(q)
                    if len(nq) < min_len or nq in seen_in_line:
                        continue
                    if not any('\u4e00' <= ch <= '\u9fff' for ch in nq) and len(nq) < 4:
                        continue
                    seen_in_line.add(nq)
                    quotes.append({'quote': q, 'source_file': str(f), 'line': i, 'norm': nq})
    return quotes


def best_match(nq, rows, only_quoted=True, threshold=0.6):
    best = None
    for f, line_no, text, ntext in rows:
        if not ntext:
            continue
        if only_quoted and not any(p.search(text) for p in QUOTE_RES):
            continue
        if abs(len(ntext) - len(nq)) > max(40, len(nq)):
            continue
        ratio = difflib.SequenceMatcher(None, nq, ntext).ratio()
        if best is None or ratio > best[0]:
            best = (ratio, f, line_no, text)
    if best and best[0] >= threshold:
        return {'ratio': round(best[0], 3), 'file': best[1], 'line': best[2],
                'text': best[3].strip()[:160]}
    return None


def main(argv=None):
    ap = argparse.ArgumentParser(description='对白保真辅助比对（只定位，不判定质量）')
    ap.add_argument('--source', action='append', required=True,
                    help='原著文件或目录，可重复')
    ap.add_argument('--script', action='append', required=True,
                    help='剧本文件或目录，可重复')
    ap.add_argument('--ledger', action='append', default=[],
                    help='对白台账文件或目录，可重复')
    ap.add_argument('--min-length', type=int, default=2, help='参与比对的引语最短字数（默认2）')
    ap.add_argument('--threshold', type=float, default=0.6, help='疑似改写相似度阈值（默认0.6）')
    ap.add_argument('--limit', type=int, default=200, help='每类最多列出条数（默认200）')
    args = ap.parse_args(argv)

    try:
        source_quotes = extract_quotes(args.source, args.min_length)
        script_rows, script_whole = load_lines(args.script)
        ledger_rows = []
        ledger_whole = ''
        if args.ledger:
            ledger_rows, ledger_whole = load_lines(args.ledger)
    except FileNotFoundError as exc:
        print(json.dumps({'ok': False, 'error': 'path not found: ' + str(exc)},
                         ensure_ascii=False, indent=2))
        return 2
    except OSError as exc:
        print(json.dumps({'ok': False, 'error': 'read error: ' + str(exc)},
                         ensure_ascii=False, indent=2))
        return 2

    unique = {}
    for item in source_quotes:
        key = item['norm']
        if key in unique:
            unique[key]['repeat'] += 1
            continue
        unique[key] = dict(item, repeat=1)

    script_lines = {row[3] for row in script_rows if row[3]}
    buckets = {'matched': [], 'ledger_only': [], 'suspected_rewrite': [], 'missing': []}

    for nq, item in unique.items():
        base = {'quote': item['quote'], 'source_file': item['source_file'],
                'line': item['line'], 'repeat': item['repeat']}
        hit = None
        hit_line = ''
        for f, line_no, text, ntext in script_rows:
            if nq and nq in ntext:
                hit = {'file': f, 'line': line_no, 'text': text.strip()[:160]}
                hit_line = text
                break
        if hit:
            lost = lost_tone(item['quote'], hit_line)
            if lost:
                buckets['suspected_rewrite'].append(
                    dict(base, script=dict(hit, reason='tone_lost', tone_lost=lost)))
            else:
                buckets['matched'].append(dict(base, script=hit))
            continue
        if nq and nq in script_whole:
            buckets['matched'].append(dict(base, script={'note': '跨行命中，需人工定位'}))
            continue
        if nq and nq in ledger_whole:
            buckets['ledger_only'].append(dict(base, note='台账已登记，确认处理状态是否为暂缓未用/用户批准改动'))
            continue
        guess = best_match(nq, script_rows, threshold=args.threshold)
        if guess:
            buckets['suspected_rewrite'].append(dict(base, script=guess))
        else:
            buckets['missing'].append(base)

    issues = [{'kind': 'missing', 'count': len(buckets['missing']),
               'detail': buckets['missing'][:args.limit]},
              {'kind': 'suspected_rewrite', 'count': len(buckets['suspected_rewrite']),
               'detail': buckets['suspected_rewrite'][:args.limit]},
              {'kind': 'ledger_only', 'count': len(buckets['ledger_only']),
               'detail': buckets['ledger_only'][:args.limit]}]
    ok = not buckets['missing'] and not buckets['suspected_rewrite']
    report = {
        'ok': ok,
        'summary': {
            'source_quotes': len(source_quotes),
            'unique_quotes': len(unique),
            'matched_in_script': len(buckets['matched']),
            'ledger_only': len(buckets['ledger_only']),
            'suspected_rewrite': len(buckets['suspected_rewrite']),
            'missing': len(buckets['missing']),
        },
        'issues': issues,
        'note': ('本脚本只按字面比对引号内文本，普通标点已忽略但省略号/破折号/问号/'
                 '感叹号会单独比对（记 reason=tone_lost）；无引号的自由直接引语不在检测范围。'
                 '引号内的书名、成语、转述语可能被误当作对白。命中不等于保真，未命中不等于违规：'
                 '以对白台账和逐句回读原文为准。'),
    }
    print(json.dumps(report, ensure_ascii=False, indent=2))
    return 0 if ok else 1


if __name__ == '__main__':
    sys.exit(main())

