#!/usr/bin/env python3
"""Offline structural gates. Passing is NOT semantic or visual approval."""
from __future__ import annotations

import argparse
import hashlib
import json
import math
from pathlib import Path
import re
import sys

KINDS = {"character", "scene", "prop", "costume", "creature", "vehicle", "text", "effect", "other"}
IMAGE_SUFFIXES = {".png", ".jpg", ".jpeg", ".webp", ".tif", ".tiff", ".bmp", ".avif"}
SHORTHAND = re.compile(r"同上|其余不变|见上文|此处省略|\b(?:same as above|ditto)\b", re.I)


class Check:
    def __init__(self, root):
        self.root = Path(root).resolve()
        self.issues = []
        self.ids = set()

    def fail(self, at, message):
        self.issues.append({"location": at, "message": message})

    def text(self, obj, key, at):
        value = obj.get(key)
        if not isinstance(value, str) or not value.strip():
            self.fail(at + "." + key, "must be a nonempty string")
            return ""
        return value

    def strings(self, obj, key, at, nonempty=False):
        value = obj.get(key)
        if not isinstance(value, list):
            self.fail(at + "." + key, "must be a string array")
            return []
        good = [v for v in value if isinstance(v, str) and v.strip()]
        if len(good) != len(value) or (nonempty and not good):
            self.fail(at + "." + key, "must contain valid nonempty strings")
        if len(set(good)) != len(good):
            self.fail(at + "." + key, "duplicate values")
        return good

    def rows(self, obj, key, at, nonempty=False):
        value = obj.get(key)
        if not isinstance(value, list):
            self.fail(at + "." + key, "must be an array of objects")
            return []
        good = [v for v in value if isinstance(v, dict)]
        if len(good) != len(value) or (nonempty and not good):
            self.fail(at + "." + key, "requires valid object entries")
        return good

    def index(self, rows, at):
        out = {}
        for i, row in enumerate(rows):
            rid = self.text(row, "id", f"{at}[{i}]")
            if rid:
                if rid in self.ids:
                    self.fail(at + "." + rid, "ID must be globally unique")
                self.ids.add(rid)
                out[rid] = row
        return out

    def number(self, value, at, allow_zero=False):
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
            self.fail(at, "must be a finite number")
            return None
        if value < 0 or (value == 0 and not allow_zero):
            self.fail(at, "must be nonnegative" if allow_zero else "must be positive")
            return None
        return value

    def file(self, value, at, image=False):
        if not isinstance(value, str) or not value.strip():
            self.fail(at, "requires a project-relative local file path")
            return None
        # Apply the same path boundary on Windows and POSIX, including UNC and drive paths.
        if Path(value).is_absolute() or re.match(r"^[A-Za-z]:", value) or "\\" in value or "://" in value:
            self.fail(at, "use a relative path with forward slashes; external paths are forbidden")
            return None
        p = (self.root / value).resolve()
        if not p.is_relative_to(self.root):
            self.fail(at, "path escapes project root")
            return None
        if image and p.suffix.lower() not in IMAGE_SUFFIXES:
            self.fail(at, "not a supported image file extension")
            return None
        try:
            if not p.is_file() or p.stat().st_size == 0:
                self.fail(at, "file missing or empty")
                return None
        except OSError as exc:
            self.fail(at, f"cannot read file: {exc}")
            return None
        return p


def validate(data, root, stage="plan"):
    c = Check(root)
    if stage not in {"plan", "media"}:
        return [{"location": "stage", "message": "expected plan or media"}]
    if not isinstance(data, dict):
        return [{"location": "$", "message": "expected JSON object"}]
    if type(data.get("schema_version")) is not int or data.get("schema_version") != 1:
        c.fail("schema_version", "expected integer 1")
    project = data.get("project")
    if not isinstance(project, dict):
        c.fail("project", "expected object")
        project = {}
    c.text(project, "title", "project")
    base_target = project.get("target_episode_seconds")
    if base_target is not None:
        base_target = c.number(base_target, "project.target_episode_seconds")
    base_tol = c.number(project.get("duration_tolerance_seconds", 0), "project.duration_tolerance_seconds", True)

    groups = {}
    for name in ("source_files", "events", "assets", "occurrences", "episodes", "scenes", "shots"):
        groups[name] = c.index(c.rows(data, name, "$", True), name)
    sources, events, assets, occurrences, episodes, scenes, shots = (groups[k] for k in groups)

    chapter_sources = {}
    for sid, src in sources.items():
        at = "source_files." + sid
        path = c.file(src.get("path"), at + ".path")
        digest = c.text(src, "sha256", at)
        if not re.fullmatch(r"[0-9a-fA-F]{64}", digest):
            c.fail(at + ".sha256", "requires SHA-256 hex")
        elif path:
            try:
                if hashlib.sha256(path.read_bytes()).hexdigest() != digest.lower():
                    c.fail(at + ".sha256", "source file changed or wrong hash")
            except OSError as exc:
                c.fail(at, f"cannot hash source: {exc}")
        for chapter in c.strings(src, "chapter_ids", at, True):
            if chapter in chapter_sources:
                c.fail(at + ".chapter_ids", "chapter ID occurs in multiple sources")
            chapter_sources[chapter] = sid
    analyzed = set(c.strings(data, "analyzed_chapters", "$", True))
    if analyzed != set(chapter_sources):
        c.fail("analyzed_chapters", "declared chapter coverage is incomplete or has unknown chapters")

    event_scene = {}
    event_shot = {}
    chapter_events = set()
    for eid, ev in events.items():
        at = "events." + eid
        c.text(ev, "summary", at)
        if type(ev.get("required")) is not bool:
            c.fail(at + ".required", "requires boolean")
        for ref in c.rows(ev, "source_refs", at, True):
            sid, chapter = ref.get("source_id"), ref.get("chapter_id")
            if not isinstance(sid, str) or not isinstance(chapter, str) or chapter_sources.get(chapter) != sid or sid not in sources:
                c.fail(at + ".source_refs", "source/chapter reference does not resolve")
            else:
                chapter_events.add(chapter)
            c.text(ref, "locator", at + ".source_refs")
        for dep in c.strings(ev, "depends_on", at):
            if dep not in events or dep == eid:
                c.fail(at + ".depends_on", "invalid dependency")
        event_scene[eid] = set(c.strings(ev, "scene_ids", at))
        event_shot[eid] = set(c.strings(ev, "shot_ids", at))
        if ev.get("required") is True and (not event_scene[eid] or not event_shot[eid]):
            c.fail(at, "required event needs scene AND shot coverage")
        for s in event_scene[eid]:
            if s not in scenes:
                c.fail(at + ".scene_ids", "unknown scene " + s)
        for s in event_shot[eid]:
            if s not in shots:
                c.fail(at + ".shot_ids", "unknown shot " + s)
    if chapter_events != set(chapter_sources):
        c.fail("events.source_refs", "each declared chapter requires event extraction")

    # Causal dependency cycle detection uses an iterative topological walk.
    deps = {eid: {v for v in ev.get("depends_on", []) if isinstance(v, str) and v in events}
            if isinstance(ev.get("depends_on"), list) else set() for eid, ev in events.items()}
    pending = {eid: len(v) for eid, v in deps.items()}
    outgoing = {eid: [] for eid in events}
    for eid, ds in deps.items():
        for dep in ds:
            outgoing[dep].append(eid)
    ready = [eid for eid, n in pending.items() if n == 0]
    seen = 0
    while ready:
        eid = ready.pop()
        seen += 1
        for child in outgoing[eid]:
            pending[child] -= 1
            if pending[child] == 0:
                ready.append(child)
    if seen != len(events):
        c.fail("events.depends_on", "causal dependency cycle")

    variants = {}
    for aid, asset in assets.items():
        at = "assets." + aid
        if asset.get("kind") not in tuple(KINDS):
            c.fail(at + ".kind", "unknown asset kind")
        for k in ("name", "definition"):
            c.text(asset, k, at)
        c.strings(asset, "anchors", at, True)
        vrows = c.rows(asset, "variants", at, True)
        for vid, var in c.index(vrows, at + ".variants").items():
            va = at + ".variants." + vid
            variants[(aid, vid)] = var
            c.text(var, "description", va)
            views = c.strings(var, "required_views", va, True)
            prompts = var.get("prompts")
            if not isinstance(prompts, dict):
                c.fail(va + ".prompts", "expected view-to-prompt object")
                prompts = {}
            for view in views:
                prompt = c.text(prompts, view, va + ".prompts")
                if SHORTHAND.search(prompt):
                    c.fail(va + ".prompts." + view, "prompt uses omitted or context-dependent description")
            media = c.rows(var, "media", va)
            indexed_media = {}
            for m in media:
                view = c.text(m, "view", va + ".media")
                if view in indexed_media or view not in views:
                    c.fail(va + ".media", "duplicate or undeclared media view")
                indexed_media[view] = m
                if stage == "media":
                    c.file(m.get("path"), va + ".media." + view, True)
                    inspection = m.get("inspection")
                    if not isinstance(inspection, dict):
                        inspection = {}
                    for flag in ("complete", "clear", "consistent"):
                        if inspection.get(flag) is not True:
                            c.fail(va + ".media." + view + "." + flag, "requires actual visual inspection recorded as true")
                    c.text(inspection, "reviewer", va + ".inspection")
                    c.text(inspection, "evidence", va + ".inspection")
            if stage == "media":
                for view in views:
                    if view not in indexed_media:
                        c.fail(va + ".media", "required view missing: " + view)

    def refs(rows, at, scene_id=None):
        found = set()
        for i, ref in enumerate(rows):
            aid = c.text(ref, "asset_id", f"{at}[{i}]")
            vid = c.text(ref, "variant_id", f"{at}[{i}]")
            pair = (aid, vid)
            if pair not in variants:
                c.fail(at, "unknown asset/variant " + str(pair))
            if pair in found:
                c.fail(at, "duplicate asset/variant reference")
            found.add(pair)
        return found

    scene_assets = {}
    scene_visible = {}
    seen_event_scenes = {eid: set() for eid in events}
    for sid, scene in scenes.items():
        at = "scenes." + sid
        ep = scene.get("episode_id")
        if not isinstance(ep, str) or ep not in episodes:
            c.fail(at + ".episode_id", "unknown episode")
        for k in ("purpose", "start_state", "end_state"):
            c.text(scene, k, at)
        for eid in c.strings(scene, "event_ids", at, True):
            if eid not in events:
                c.fail(at + ".event_ids", "unknown event")
            else:
                seen_event_scenes[eid].add(sid)
        rows = c.rows(scene, "asset_refs", at, True)
        scene_assets[sid] = refs(rows, at + ".asset_refs")
        scene_visible[sid] = set()
        for ref in rows:
            if ref.get("visibility") not in ("visible", "offscreen"):
                c.fail(at + ".asset_refs.visibility", "expected visible or offscreen")
            elif ref.get("visibility") == "visible":
                aid, vid = ref.get("asset_id"), ref.get("variant_id")
                if isinstance(aid, str) and isinstance(vid, str):
                    scene_visible[sid].add((aid, vid))
        if not scene_visible[sid]:
            c.fail(at, "scene requires visible assets, including its location")

    by_scene = {sid: set() for sid in scenes}
    registered_assets = set()
    for oid, occ in occurrences.items():
        sid = occ.get("scene_id")
        pair = refs([occ], "occurrences." + oid)
        if not isinstance(sid, str) or sid not in scenes:
            c.fail("occurrences." + oid, "unknown scene")
        else:
            by_scene[sid].update(pair)
        registered_assets.update(a for a, v in pair)
    for sid in scenes:
        if by_scene[sid] != scene_assets[sid]:
            c.fail("scenes." + sid, "occurrence inventory and scene asset references disagree")
    if registered_assets != set(assets):
        c.fail("assets", "unreferenced assets or occurrence references without assets")

    shown = {sid: set() for sid in scenes}
    scene_shots = {sid: [] for sid in scenes}
    seen_event_shots = {eid: set() for eid in events}
    episode_duration = {eid: 0 for eid in episodes}
    episode_counts = {eid: 0 for eid in episodes}
    for shid, shot in shots.items():
        at = "shots." + shid
        sid = shot.get("scene_id")
        if not isinstance(sid, str) or sid not in scenes:
            c.fail(at + ".scene_id", "unknown scene")
            sid = None
        for k in ("purpose", "start_state", "end_state", "frame_prompt", "motion_prompt"):
            value = c.text(shot, k, at)
            if k.endswith("prompt") and SHORTHAND.search(value):
                c.fail(at + "." + k, "prompt must be independently usable")
        duration = c.number(shot.get("duration_seconds"), at + ".duration_seconds")
        event_ids = c.strings(shot, "event_ids", at, True)
        for eid in event_ids:
            if eid not in events:
                c.fail(at + ".event_ids", "unknown event")
            else:
                seen_event_shots[eid].add(shid)
            scene_events = scenes[sid].get("event_ids") if sid else []
            if not isinstance(scene_events, list) or eid not in scene_events:
                c.fail(at + ".event_ids", "shot event not carried by its scene")
        visible = refs(c.rows(shot, "visible_assets", at, True), at + ".visible_assets")
        if sid:
            shown[sid].update(visible)
            scene_shots[sid].append(shid)
            if not visible <= scene_visible[sid]:
                c.fail(at + ".visible_assets", "shot shows asset absent or offscreen in scene")
            ep = scenes[sid].get("episode_id")
            if isinstance(ep, str) and ep in episodes:
                episode_duration[ep] += duration or 0
                episode_counts[ep] += 1
    for sid in scenes:
        if not scene_shots[sid]:
            c.fail("scenes." + sid, "scene has no shots")
        if shown[sid] != scene_visible[sid]:
            c.fail("scenes." + sid, "visible scene assets are missing shot coverage")
    for eid in events:
        if event_scene[eid] != seen_event_scenes[eid] or event_shot[eid] != seen_event_shots[eid]:
            c.fail("events." + eid, "event-to-scene/shot references must agree in both directions")
    for ep, episode in episodes.items():
        at = "episodes." + ep
        if not episode_counts[ep]:
            c.fail(at, "episode has no shots")
        target = episode.get("target_seconds", base_target)
        tolerance = c.number(episode.get("tolerance_seconds", base_tol), at + ".tolerance_seconds", True)
        if target is not None:
            target = c.number(target, at + ".target_seconds")
            if target is not None and tolerance is not None and abs(episode_duration[ep] - target) > tolerance + 1e-8:
                c.fail(at, f"shot duration total {episode_duration[ep]} differs from target {target}")

    review = data.get("review")
    if not isinstance(review, dict):
        c.fail("review", "requires content review object")
        review = {}
    if review.get("mode") not in ("independent_agent", "self_review"):
        c.fail("review.mode", "declare actual review mode")
    if review.get("content_status") != "passed":
        c.fail("review.content_status", "content review is not passed")
    c.file(review.get("report_path"), "review.report_path")
    if stage == "media" and review.get("visual_status") != "passed":
        c.fail("review.visual_status", "visual review is not passed")
    for fid, finding in c.index(c.rows(review, "findings", "review"), "review.findings").items():
        at = "review.findings." + fid
        if finding.get("severity") not in ("blocker", "major", "minor", "note"):
            c.fail(at, "unknown severity")
        if finding.get("status") not in ("open", "closed"):
            c.fail(at, "unknown finding status")
        for k in ("location", "evidence", "owner", "required_fix"):
            c.text(finding, k, at)
        if finding.get("severity") in ("blocker", "major") and finding.get("status") != "closed":
            c.fail(at, "unresolved blocking/major finding")
    return c.issues


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("manifest", type=Path)
    parser.add_argument("--stage", choices=("plan", "media"), default="plan")
    args = parser.parse_args()
    try:
        data = json.loads(args.manifest.read_text(encoding="utf-8-sig"))
        issues = validate(data, args.manifest.parent, args.stage)
    except (OSError, ValueError, RecursionError) as exc:
        print(json.dumps({"ok": False, "error": str(exc)}, ensure_ascii=False))
        return 2
    print(json.dumps({"ok": not issues, "stage": args.stage, "issues": issues,
                      "limit": "Structural checks only; source fidelity, completeness and image quality require actual review."},
                     ensure_ascii=False, indent=2))
    return 1 if issues else 0


if __name__ == "__main__":
    sys.exit(main())

